var i=`1173-tostadas`;var a=`world-1173`;var t=`MX`;var s=`central-america-caribbean`;var o=8;var r=35;var d={en:`Tostadas`,ua:`Тостадас`};var l={en:`Tostadas is a dish from Mexico prepared with corn tortillas, ground beef, yellow onion, canned black beans. This is a home-scale version with measured ingredients in the individual steps where they are used. Canned black beans warmed and mashed replace prepared refried beans.`,ua:`Тостадас, страва кухні країни Мексика, яку готують із таких продуктів: кукурудзяні тортильї, яловичий фарш, жовта цибуля, консервована чорна квасоля. Кількості в домашньому рецепті прив’язані до окремих етапів приготування. Підігріта розім’ята чорна квасоля замінює готову пересмажену.`};var g=[{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 10 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 10 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:10,i:[[`corn-tortillas`,12,`pcs`],[`canola-oil`,450,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`ground-beef`,430,`g`],[`yellow-onion`,150,`g`],[`ground-cumin`,5,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 6 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 6 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:6,i:[[`canned-black-beans`,260,`g`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:7,i:[[`lettuce`,190,`g`],[`tomato`,190,`g`],[`queso-fresco`,170,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`red-salsa`,130,`g`]]}];var u={slug:i,id:a,country:`MX`,region:s,servings:8,minutes:35,title:d,text:l,steps:g};export{t as country,u as default,a as id,r as minutes,s as region,o as servings,i as slug,g as steps,l as text,d as title};